function xp_has(string $t):bool{return (bool)g('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[$t]);}
function xp_ready():bool{return xp_has('xp_config')&&xp_has('xp_requests')&&xp_has('xp_enrolments');}
function xp_install():void{global $pdo;ecoMigrate();saasMigrate();v23migrate();foreach([
