"CREATE TABLE IF NOT EXISTS xp_progress(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,step VARCHAR(40) NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,user_id,step)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS xp_rates(bucket CHAR(64) PRIMARY KEY,attempts INT NOT NULL,expires_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
] as $sql)$pdo->exec($sql);q("INSERT IGNORE INTO xp_config VALUES('registrations','0'),('join','1'),('trial_policy','plans')");q('INSERT IGNORE INTO xp_config VALUES(?,?)',['rate_salt',bin2hex(random_bytes(24))]);q('INSERT IGNORE INTO xp_config VALUES(?,?)',['demo_owner',bin2hex(random_bytes(32))]);}
function xp_setting(string $key,string $default=''):string{if(!xp_has('xp_config'))return $default;$r=q('SELECT value FROM xp_config WHERE name=?',[$key])->fetchColumn();return $r===false?$default:(string)$r;}
function xp_text(string $key,int $max=200,bool $required=true):string{$v=$_POST[$key]??'';if(!is_string($v))throw new RuntimeException('Check '.$key.'.');$v=trim($v);if(mb_strlen($v)>$max||($required&&$v===''))throw new RuntimeException('Check '.$key.'.');return $v;}
function xp_csrf():void{if(!is_string($_POST['csrf']??null)||!hash_equals((string)($_SESSION['csrf']??''),$_POST['csrf']))throw new RuntimeException('Security token expired. Refresh this page.');}
function xp_tx(callable $fn):mixed{global $pdo;$pdo->beginTransaction();try{$r=$fn();$pdo->commit();return $r;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function xp_rate(string $purpose,int $max=8,int $minutes=15):void{if(!xp_ready())return;$key=hash_hmac('sha256',$purpose.'|'.($_SERVER['REMOTE_ADDR']??'local').'|'.intdiv(time(),$minutes*60),xp_setting('rate_salt'));xp_tx(function()use($key,$max,$minutes){q('INSERT IGNORE INTO xp_rates VALUES(?,0,?)',[$key,date('Y-m-d H:i:s',time()+$minutes*60)]);$n=(int)g('SELECT attempts FROM xp_rates WHERE bucket=? FOR UPDATE',[$key]);if($n>=$max)throw new RuntimeException('Too many attempts. Please try again later.');q('UPDATE xp_rates SET attempts=attempts+1 WHERE bucket=?',[$key]);});q('DELETE FROM xp_rates WHERE expires_at<NOW()');}
function xp_identity():array{$name=xp_text('name',180);$email=mb_strtolower(xp_text('email',190));$password=xp_text('password',200);if(str_ends_with($email,'@demo.schoolos.test'))throw new RuntimeException('That email domain is reserved for the isolated demo. Use your own email address.');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||strlen($password)>72)throw new RuntimeException('Use a valid email and a password of 12–72 characters.');if(xp_text('terms',10,false)!=='yes'||xp_text('website',100,false)!=='')throw new RuntimeException('Confirm the privacy and account terms.');return [$name,$email,password_hash($password,PASSWORD_DEFAULT)];}
function xp_register_school():int{if(!xp_ready()||xp_setting('registrations')!=='1')throw new RuntimeException('School registration is not enabled yet. Contact the platform team.');xp_csrf();xp_rate('school-register',5,60);[$name,$email,$hash]=xp_identity();$school=xp_text('school_name',180);$state=xp_text('state',80);$type=xp_text('school_type',80);if($state==='Abuja FCT')$state='FCT';if(!in_array($state,explode('|','Abia|Adamawa|Akwa Ibom|Anambra|Bauchi|Bayelsa|Benue|Borno|Cross River|Delta|Ebonyi|Edo|Ekiti|Enugu|FCT|Gombe|Imo|Jigawa|Kaduna|Kano|Katsina|Kebbi|Kogi|Kwara|Katsina|Kebbi|Kogi|Lagos|Nasarawa|Niger|Ogun|Ondo|Osun|Oyo|Plateau|Rivers|Sokoto|Taraba|Yobe|Zamfara'),true))throw new RuntimeException('Choose a Nigerian state or FCT.');$cycle=xp_text('cycle',12);if(!in_array($cycle,['monthly','termly','annual'],true))throw new RuntimeException('Choose a billing cycle.');$request=xp_text('request_key',64);if(!preg_match('/^[a-f0-9]{64}$/D',$request)||!hash_equals((string)($_SESSION['xp_register_key']??''),$request))throw new RuntimeException('Registration form expired.');return xp_tx(function()use($name,$email,$hash,$school,$state,$type,$cycle,$request){global $pdo;$prior=q('SELECT * FROM xp_enrolments WHERE request_key=? FOR UPDATE',[$request])->fetch();if($prior)return (int)$prior['tenant_id'];$plan=q('SELECT * FROM saas_plans WHERE id=? AND active=1 FOR UPDATE',[(int)xp_text('plan_id',20)])->fetch();if(!$plan)throw new RuntimeException('Choose an available subscription plan.');if(g('SELECT id FROM users WHERE email=?',[$email]))throw new RuntimeException('Unable to register with these details. Sign in if you already have an account.');$price=(int)round((float)$plan[$cycle.'_price']*100);if($price<0)throw new RuntimeException('Plan is not configured correctly.');if($price===0&&max((float)$plan['monthly_price'],(float)$plan['termly_price'],(float)$plan['annual_price'])>0)throw new RuntimeException('This billing cycle is not offered for the selected paid plan.');$days=xp_setting('trial_policy','plans')==='payment'?0:max(0,min(90,(int)$plan['trial_days']));$status=$price===0?'active':($days>0?'trial':'pending');q('INSERT INTO tenants(name,state,school_type) VALUES(?,?,?)',[$school,$state,$type]);$tid=(int)$pdo->lastInsertId();q("INSERT INTO users(tenant_id,email,password_hash,role,name,active) VALUES(?,?,?,'school_admin',?,1)",[$tid,$email,$hash,$name]);$uid=(int)$pdo->lastInsertId();$expiry=$status==='active'?(new DateTimeImmutable())->modify('+'.['monthly'=>1,'termly'=>4,'annual'=>12][$cycle].' months')->format('Y-m-d H:i:s'):date('Y-m-d H:i:s',time()+$days*86400);q('INSERT INTO saas_subscriptions(tenant_id,plan_id,billing_cycle,status,started_at,expires_at) VALUES(?,?,?,?,NOW(),?)',[$tid,$plan['id'],$cycle,$status,$expiry]);$sub=(int)$pdo->lastInsertId();q('INSERT INTO xp_enrolments(tenant_id,owner_id,plan_id,cycle,price_kobo,request_key,subscription_id) VALUES(?,?,?,?,?,?,?)',[$tid,$uid,$plan['id'],$cycle,$price,$request,$sub]);q('INSERT INTO saas_tenant_status(tenant_id,status,reason) VALUES(?,?,?)',[$tid,$status==='pending'?'pending':'active','Self-service school subscription']);q('INSERT INTO xp_schools VALUES(?,?,0,0)',[$tid,bin2hex(random_bytes(16))]);q('INSERT INTO audit_logs(tenant_id,user_id,action,entity_type,details,ip_address) VALUES(?,?,?,?,?,?)',[$tid,$uid,'experience.school.created','tenant','Subscription '.$status,$_SERVER['REMOTE_ADDR']??'']);$_SESSION['xp_created_owner']=$uid;return $tid;});}
function xp_join():void{if(!xp_ready()||xp_setting('join','1')!=='1')throw new RuntimeException('Use a school administrator invitation.');xp_csrf();xp_rate('join',6,60);[$name,$email,$hash]=xp_identity();$role=xp_text('requested_role',30);if(!isset(xp_join_roles()[$role]))throw new RuntimeException('Choose a school role.');$school=(int)xp_text('school_id',20,false);$code=xp_text('school_code',32,false);$settings=$code!==''?q('SELECT * FROM xp_schools WHERE join_code=? AND requests_enabled=1',[$code])->fetch():q('SELECT * FROM xp_schools WHERE tenant_id=? AND listed=1 AND requests_enabled=1',[$school])->fetch();if(!$settings)throw new RuntimeException('School is not accepting requests. Ask for its invitation code.');if(in_array((string)g('SELECT status FROM saas_tenant_status WHERE tenant_id=?',[$settings['tenant_id']]),['suspended','pending'],true))throw new RuntimeException('This school is not accepting new requests right now. Contact its administrator.');$note=xp_text('reference_note',500);xp_tx(function()use($settings,$name,$email,$hash,$role,$note){global $pdo;if(g('SELECT id FROM users WHERE email=?',[$email]))throw new RuntimeException('Unable to submit these details. Contact your school if an account already exists.');q('INSERT INTO users(tenant_id,email,password_hash,role,name,active) VALUES(?,?,?,?,?,0)',[$settings['tenant_id'],$email,$hash,$role==='driver'||$role==='warden'?'staff':$role,$name]);$uid=(int)$pdo->lastInsertId();q('INSERT INTO xp_requests(tenant_id,user_id,requested_role,reference_note) VALUES(?,?,?,?)',[$settings['tenant_id'],$uid,$role,$note]);});}
function xp_join_roles():array{return ['parent'=>'Parent / guardian','student'=>'Student','teacher'=>'Teacher','staff'=>'School staff','driver'=>'Transport driver','warden'=>'Boarding warden','admissions'=>'Admissions officer'];}
function xp_subscription(array $u):?array{if(!xp_ready()||empty($u['tenant_id']))return null;return q('SELECT e.*,s.status,s.expires_at,p.name plan_name FROM xp_enrolments e JOIN saas_subscriptions s ON s.id=e.subscription_id AND s.tenant_id=e.tenant_id JOIN saas_plans p ON p.id=e.plan_id WHERE e.tenant_id=?',[$u['tenant_id']])->fetch()?:null;}
function xp_subscription_allowed(array $u):bool{$s=xp_subscription($u);if(!$s)return true;$state=(string)g('SELECT status FROM saas_tenant_status WHERE tenant_id=?',[$u['tenant_id']]);return $state==='active'&&in_array($s['status'],['active','trial'],true)&&$s['expires_at']>date('Y-m-d H:i:s');}
function xp_checkout(array $u,?callable $api=null):string{if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');if(defined('SCHOOLOS_DEMO_MODE'))throw new RuntimeException('Live checkout is disabled in the demo.');$s=xp_subscription($u);if(!$s||$s['price_kobo']<=0)throw new RuntimeException('No paid subscription is pending.');$origin=xp_setting('origin');if(!filter_var($origin,FILTER_VALIDATE_URL)||parse_url($origin,PHP_URL_SCHEME)!=='https'||parse_url($origin,PHP_URL_QUERY)||parse_url($origin,PHP_URL_FRAGMENT)||parse_url($origin,PHP_URL_USER))throw new RuntimeException('The platform team must configure the canonical HTTPS installation address.');$reference='JOIN-'.bin2hex(random_bytes(16));$id=xp_tx(function()use($u,$s,$reference){global $pdo;q('INSERT INTO saas_transactions(tenant_id,subscription_id,reference,amount,status) VALUES(?,?,?,?,?)',[$u['tenant_id'],$s['subscription_id'],$reference,$s['price_kobo']/100,'pending']);$transaction=(int)$pdo->lastInsertId();q('INSERT INTO xp_payments(tenant_id,subscription_id,transaction_id,reference,amount_kobo,cycle) VALUES(?,?,?,?,?,?)',[$u['tenant_id'],$s['subscription_id'],$transaction,$reference,$s['price_kobo'],$s['cycle']]);return (int)$pdo->lastInsertId();});$api??='v23paystack';$data=$api('POST','/transaction/initialize',['email'=>$u['email'],'amount'=>(int)$s['price_kobo'],'currency'=>'NGN','reference'=>$reference,'callback_url'=>rtrim($origin,'/').'/index.php?s=welcome&checkout_return=1']);$url=(string)($data['authorization_url']??'');if(!preg_match('~^https://checkout\.paystack\.com/[A-Za-z0-9_-]+$~D',$url))throw new RuntimeException('Checkout could not be created. Pending reference retained for reconciliation.');q('UPDATE xp_payments SET checkout_url=? WHERE tenant_id=? AND id=?',[$url,$u['tenant_id'],$id]);return $url;}
function xp_verify(array $u,int $id,?callable $api=null):string{if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');if(defined('SCHOOLOS_DEMO_MODE'))throw new RuntimeException('Real payments are disabled in the demo.');$p=q('SELECT * FROM xp_payments WHERE tenant_id=? AND id=?',[$u['tenant_id'],$id])->fetch();if(!$p)throw new RuntimeException('Checkout unavailable.');if($p['status']==='success')return 'Payment already verified.';$api??='v23paystack';$d=$api('GET','/transaction/verify/'.rawurlencode($p['reference']));if(($d['status']??'')!=='success'||($d['reference']??'')!==$p['reference']||($d['currency']??'')!=='NGN'||(int)($d['amount']??-1)!==(int)$p['amount_kobo'])throw new RuntimeException('Provider has not verified the exact NGN amount and reference.');return xp_tx(function()use($u,$id){$p=q('SELECT * FROM xp_payments WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$id])->fetch();if($p['status']==='success')return 'Payment already verified.';$s=q('SELECT * FROM saas_subscriptions WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$p['subscription_id']])->fetch();if(!$s)throw new RuntimeException('Subscription unavailable.');$base=max(time(),strtotime($s['expires_at']));$expiry=(new DateTimeImmutable('@'.$base))->setTimezone(new DateTimeZone('Africa/Lagos'))->modify('+'.['monthly'=>1,'termly'=>4,'annual'=>12][$p['cycle']].' months')->format('Y-m-d H:i:s');q("UPDATE saas_subscriptions SET status='active',expires_at=? WHERE tenant_id=? AND id=?",[$expiry,$u['tenant_id'],$s['id']]);q("UPDATE xp_payments SET status='success' WHERE tenant_id=? AND id=?",[$u['tenant_id'],$id]);q("UPDATE saas_transactions SET status='success',verified_at=NOW() WHERE tenant_id=? AND id=?",[$u['tenant_id'],$p['transaction_id']]);q("UPDATE saas_tenant_status SET status='active',reason='Verified subscription payment' WHERE tenant_id=? AND status='pending'",[$u['tenant_id']]);audit('experience.subscription.verified','payment',(string)$id);return 'Payment verified. Your school workspace is ready.';});}
function xp_demo_connection():PDO{global $pdo,$xpDemoDb;if(xp_setting('demo_refreshing')==='1')throw new RuntimeException('Demo maintenance is in progress. Try again shortly.');static $settings=null;if($settings===null){$settings=[];foreach(['host','name','user','pass'] as $key)$settings[$key]=v23secret('xp_demo_'.$key);$settings['owner']=xp_setting('demo_owner');}if(!str_ends_with($settings['name'],'_demo')||$settings['name']===(string)g('SELECT DATABASE()'))throw new RuntimeException('An isolated demo database must be configured by the platform team.');$d=new PDO('mysql:host='.$settings['host'].';dbname='.$settings['name'].';charset=utf8mb4',$settings['user'],$settings['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$owner=$d->query("SELECT value FROM xp_config WHERE name='demo_marker'")->fetchColumn();if(!$owner||!hash_equals($settings['owner'],(string)$owner))throw new RuntimeException('Demo database validation failed.');$d->exec("SET time_zone='+01:00'");$xpDemoDb=array_intersect_key($settings,array_flip(['host','name','user','pass']));return $d;}
