 if(me()){$fresh=q('SELECT * FROM users WHERE id=? AND active=1',[me()['id']])->fetch();if(!$fresh||$fresh['role']!==me()['role']||$fresh['tenant_id']!=me()['tenant_id']){$_SESSION=[];session_destroy();header('Location:index.php?login=1');exit;}$_SESSION['u']=$fresh;}
 if(isset($_POST['login'])){try{xp_csrf();xp_rate('login|'.mb_strtolower(xp_text('email',190)),15,15);if(isset($_POST['demo_mode'])&&!defined('SCHOOLOS_DEMO_MODE')){$pdo=xp_demo_connection();define('SCHOOLOS_DEMO_MODE',true);$c=['db'=>$xpDemoDb,'app'=>['name'=>'SchoolOS Demo','timezone'=>'Africa/Lagos','cms_origin'=>'https://demo.invalid']];}$email=mb_strtolower(xp_text('email',190));$pw=xp_text('password',200);$u=q('SELECT * FROM users WHERE email=? AND active=1',[$email])->fetch();if(!$u||!password_verify($pw,$u['password_hash']))throw new RuntimeException('Check your email and password. New school-member accounts require administrator approval.');$initial=xp_has('xp_requests')?q("SELECT temp_expires_at FROM xp_requests WHERE user_id=? AND status='approved' AND must_change=1",[$u['id']])->fetch():false;if($initial&&(!$initial['temp_expires_at']||$initial['temp_expires_at']<=date('Y-m-d H:i:s')))throw new RuntimeException('Temporary credential expired. Contact your school administrator.');xp_session_login(defined('SCHOOLOS_DEMO_MODE'));$_SESSION['u']=$u;if(defined('SCHOOLOS_DEMO_MODE'))$_SESSION['xp_demo']=true;header('Location:index.php?s=workspace');exit;}catch(Throwable $e){$err=isset($_POST['demo_mode'])?'The demo is unavailable or the details are incorrect. Ask the platform team to check its sandbox configuration.':$e->getMessage();$pdo=$real;}}
 if(isset($_GET['xp_privacy'])){header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store');echo '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account and privacy information · SchoolOS</title><main style="font:16px/1.8 system-ui;max-width:760px;margin:50px auto;padding:20px"><h1>Your school account and information</h1><p>School owners provide school and administrator details to create a workspace and arrange the selected subscription. School members provide their name, email, requested role and school reference for administrator verification. Passwords are stored as hashes. Pending requests do not grant access to school records.</p><p>The school is responsible for verifying identities, child relationships, lawful processing purposes and applicable privacy notices. Ask your school or platform administrator about access, corrections, retention, deletion requests and support. Schools configure their own child-data processing and review workflows. Use your own account and keep passwords private.</p><p>Only platform-configured subscription plans are offered. Payment is confirmed by server-side provider verification, not a browser return. Trials follow the selected plan. This release does not automatically charge renewals.</p><p>Demo data are fictional and shared. Never enter real personal or payment details in the demo. Live external providers are disabled there.</p><p><a href="?login=1">Return to SchoolOS</a></p></main></html>';exit;}
 if(isset($_GET['register'])||isset($_GET['join'])||isset($_GET['login'])){if(isset($_POST['xp_public'])){try{if($_POST['xp_public']==='school'){xp_register_school();session_regenerate_id(true);$_SESSION['u']=q('SELECT * FROM users WHERE id=?',[$_SESSION['xp_created_owner']])->fetch();header('Location:index.php?s=welcome&created=1');exit;}elseif($_POST['xp_public']==='join'){xp_join();$_SESSION['xp_public_success']='Your request is with the school. An administrator must verify your identity, role and record links before you can sign in.';header('Location:index.php?join=1&submitted=1',true,303);exit;}}catch(Throwable $e){$err=$e instanceof PDOException?'Unable to complete this request. Please try again or contact your school.':$e->getMessage();}}xp_auth_view(isset($_GET['register'])?'school':(isset($_GET['join'])?'join':'login'),$err??'');exit;}
 if(me()&&xp_has('xp_requests')&&g("SELECT id FROM xp_requests WHERE tenant_id=? AND user_id=? AND status='approved' AND must_change=1",[me()['tenant_id'],me()['id']])){$passwordError='';if(isset($_POST['xp_initial_password'])){try{xp_csrf();xp_change_password(me(),xp_text('new_password',72));header('Location:index.php?s=workspace',true,303);exit;}catch(Throwable $ex){$passwordError=$ex->getMessage();}}xp_password_view(me(),$passwordError);}
