}

function xp_change_password(array $u,string $password):void{if(strlen($password)<12||strlen($password)>72)throw new RuntimeException('Use a password of 12–72 characters.');xp_tx(function()use($u,$password){$r=q("SELECT * FROM xp_requests WHERE tenant_id=? AND user_id=? AND status='approved' AND must_change=1 FOR UPDATE",[$u['tenant_id'],$u['id']])->fetch();if(!$r)throw new RuntimeException('No initial password change is pending.');if(!$r['temp_expires_at']||$r['temp_expires_at']<=date('Y-m-d H:i:s'))throw new RuntimeException('Temporary credential expired. Ask your school administrator for a new one.');$hash=(string)g('SELECT password_hash FROM users WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$u['id']]);if(password_verify($password,$hash))throw new RuntimeException('Choose a new password, different from your temporary one.');q('UPDATE users SET password_hash=? WHERE tenant_id=? AND id=?',[password_hash($password,PASSWORD_DEFAULT),$u['tenant_id'],$u['id']]);q('UPDATE xp_requests SET must_change=0,temp_expires_at=NULL WHERE tenant_id=? AND user_id=?',[$u['tenant_id'],$u['id']]);});if(session_status()===PHP_SESSION_ACTIVE)session_regenerate_id(true);}
function xp_password_view(array $u,string $error=''):void{header('Cache-Control: no-store');echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Make your account yours · SchoolOS</title>';xp_asset_head();echo '</head><body class="xp-simple"><main class="xp-panel"><span class="xp-eyebrow">YOUR FIRST SECURE STEP</span><h1>Make this account yours.</h1><p>Your school has verified your request. Replace the temporary password with your own before opening school records. Use 12–72 characters and avoid a password you use elsewhere.</p>';if($error)echo '<div class="xp-alert" role="alert">'.e($error).'</div>';echo '<form method="post" class="xp-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="xp_initial_password" value="1"><label>New password<input type="password" name="new_password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit" class="btn">Save my password & continue →</button></form><a href="?logout=1">Sign out</a></main></body></html>';exit;}
function xp_renew_free(array $u):string{if($u['role']!=='school_admin'||defined('SCHOOLOS_DEMO_MODE'))throw new RuntimeException('School administrator required.');return xp_tx(function()use($u){$s=xp_subscription($u);if(!$s||(int)$s['price_kobo']!==0)throw new RuntimeException('This school does not have a free plan.');$plan=q('SELECT * FROM saas_plans WHERE id=? AND active=1 FOR UPDATE',[$s['plan_id']])->fetch();$sub=q('SELECT * FROM saas_subscriptions WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$s['subscription_id']])->fetch();if(!$plan||max((float)$plan['monthly_price'],(float)$plan['termly_price'],(float)$plan['annual_price'])>0||$sub['expires_at']>date('Y-m-d H:i:s'))throw new RuntimeException('Free renewal is unavailable or not due. Ask the platform team to review the plan.');if((string)g('SELECT status FROM saas_tenant_status WHERE tenant_id=?',[$u['tenant_id']])==='suspended')throw new RuntimeException('Administrative suspension requires platform review.');$expiry=(new DateTimeImmutable())->modify('+'.['monthly'=>1,'termly'=>4,'annual'=>12][$s['cycle']].' months')->format('Y-m-d H:i:s');q("UPDATE saas_subscriptions SET status='active',expires_at=? WHERE tenant_id=? AND id=?",[$expiry,$u['tenant_id'],$s['subscription_id']]);q("UPDATE saas_tenant_status SET status='active' WHERE tenant_id=? AND status='pending'",[$u['tenant_id']]);audit('experience.free.renewal','subscription',(string)$s['subscription_id']);return 'Configured free plan renewed. No payment was created or charged.';});}

function xp_demo_cookie(bool $enabled):void{$path=str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/index.php'));if($path==='.'||$path==='/')$path='/';else $path=rtrim($path,'/').'/';setcookie('SchoolOSDemoMode'.substr(hash('sha256',__DIR__),0,8),$enabled?'1':'',['expires'=>$enabled?0:time()-3600,'path'=>$path,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);}
function xp_session_login(bool $demo):void{$_SESSION=[];session_destroy();session_id('');$suffix=substr(hash('sha256',__DIR__),0,8);if($demo){$path=__DIR__.'/storage/system/demo-sessions';if(is_link($path)||(!is_dir($path)&&!mkdir($path,0700,true)))throw new RuntimeException('Private demo session storage unavailable.');session_name('SCHOOLOSDEMO'.$suffix);session_save_path($path);}else{session_name(defined('SCHOOLOS_REAL_SESSION_NAME')?SCHOOLOS_REAL_SESSION_NAME:'PHPSESSID');session_save_path(defined('SCHOOLOS_REAL_SESSION_PATH')?SCHOOLOS_REAL_SESSION_PATH:session_save_path());}session_start();session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));xp_demo_cookie($demo);}
